import React, { PropsWithChildren } from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

//#region Typings
/** Accepted properties for the Select Prefix */
export type SelectV2PrefixProps = PropsWithChildren<unknown> &
  StylingProps &
  DataTestId;
//#endregion

/**
 * Typeguard function that will check if a React.Node is a SelectV2.Prefix
 * @internal
 */
export function _isSelectV2PrefixElement(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2PrefixProps> {
  if (isElement(child) && child.type === SelectV2Prefix) {
    return true;
  }
  return false;
}

/**
 * The `SelectV2.Prefix` component allows you to specify any content, that should
 * be prefixed in the trigger element. The `SelectV2.Prefix` component is only valid
 * within the `SelectV2.Trigger` and `SelectV2.Option` element.
 * @example
 * ```tsx
 * <SelectV2.DisplayValue>
 *   <SelectV2.Prefix>
 *     <WhatsNewIcon />
 *   </SelectV2.Prefix>
 * </SelectV2.DisplayValue>
 * ```
 */
export function SelectV2Prefix(props: SelectV2PrefixProps) {
  return null;
}

SelectV2Prefix.displayName = 'Select.Prefix';
